{"output":"import { ReloadOutlined } from '@ant-design/icons';
import {
  Alert,
  Button,
  Card,
  Input,
  Progress,
  Segmented,
  Select,
  Space,
  Statistic,
  Switch,
  Table,
  Tag,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { axiosInstance } from '../api/client';
import type { Subsystem } from '../api/types';

const SubsystemListPage = () => {
  const navigate = useNavigate();
  const [allSubsystems, setAllSubsystems] = useState<Subsystem[]>([]);
  const [filteredSubsystems, setFilteredSubsystems] = useState<Subsystem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchValue, setSearchValue] = useState('');
  const [selectedDisciplines, setSelectedDisciplines] = useState<string[]>([]);
  const [progressFilter, setProgressFilter] = useState<'all' | 'lt50' | '50to90' | 'gt90'>('all');
  const [onlyOpenPunch, setOnlyOpenPunch] = useState(false);

  const filterSubsystems = useCallback(
    (source: Subsystem[]) => {
      const term = searchValue.trim().toLowerCase();

      return source.filter((subsystem) => {
        const discipline = subsystem.discipline ?? '';
        const progress = subsystem.progress_pct ?? 0;
        const hasOpenPunch =
          (subsystem.tag_with_punch ?? 0) > 0 || (subsystem.mcr_closed ?? 0) < (subsystem.mcr_total ?? 0);

        const matchesDiscipline =
          selectedDisciplines.length === 0 || selectedDisciplines.includes(discipline);

        const matchesProgress = (() => {
          switch (progressFilter) {
            case 'lt50':
              return progress < 50;
            case '50to90':
              return progress >= 50 && progress <= 90;
            case 'gt90':
              return progress > 90;
            default:
              return true;
          }
        })();

        const matchesPunchFilter = !onlyOpenPunch || hasOpenPunch;

        const matchesSearch = !term
          ? true
          : [subsystem.sys_code, subsystem.subsys_code, discipline]
              .join(' ')
              .toLowerCase()
              .includes(term);

        return matchesDiscipline && matchesProgress && matchesPunchFilter && matchesSearch;
      });
    },
    [onlyOpenPunch, progressFilter, searchValue, selectedDisciplines],
  );

  const applyFilters = useCallback(
    (source?: Subsystem[]) => {
      const baseList = source ?? allSubsystems;
      setFilteredSubsystems(filterSubsystems(baseList));
    },
    [allSubsystems, filterSubsystems],
  );

  const loadSubsystems = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await axiosInstance.get<Subsystem[]>('/subsystems/');
      setAllSubsystems(response.data);
      setFilteredSubsystems(filterSubsystems(response.data));
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load subsystems';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [filterSubsystems]);

  useEffect(() => {
    void loadSubsystems();
  }, [loadSubsystems]);

  useEffect(() => {
    applyFilters();
  }, [applyFilters]);

  const totals = useMemo(() => {
    return allSubsystems.reduce(
      (
        acc,
        { tag_total, mcr_total, mcr_closed, tag_with_punch: tagsWithPunch },
      ) => {
        acc.tag_total += tag_total ?? 0;
        acc.mcr_total += mcr_total ?? 0;
        acc.mcr_closed += mcr_closed ?? 0;
        acc.tag_with_punch += tagsWithPunch ?? 0;
        return acc;
      },
      { tag_total: 0, mcr_total: 0, mcr_closed: 0, tag_with_punch: 0 },
    );
  }, [allSubsystems]);

  const disciplineOptions = useMemo(() => {
    const unique = new Set<string>();
    allSubsystems.forEach((item) => {
      if (item.discipline) {
        unique.add(item.discipline);
      }
    });
    return Array.from(unique).sort((a, b) => a.localeCompare(b));
  }, [allSubsystems]);

  const disciplineSelectOptions = useMemo(
    () => [
      { label: 'All disciplines', value: '__all__' },
      ...disciplineOptions.map((value) => ({ label: value, value })),
    ],
    [disciplineOptions],
  );

  const handleDisciplineChange = (values: string[]) => {
    if (values.includes('__all__')) {
      setSelectedDisciplines([]);
      return;
    }
    setSelectedDisciplines(values);
  };

  const columns: ColumnsType<Subsystem> = [
    {
      title: 'System',
      dataIndex: 'sys_code',
      sorter: (a, b) => a.sys_code.localeCompare(b.sys_code),
    },
    {
      title: 'Subsystem',
      dataIndex: 'subsys_code',
      sorter: (a, b) => a.subsys_code.localeCompare(b.subsys_code),
    },
    {
      title: 'Discipline',
      dataIndex: 'discipline',
      render: (value: string | null) =>
        value ? <Tag color="blue">{value}</Tag> : <Typography.Text type="secondary">N/A</Typography.Text>,
    },
    {
      title: 'MCR Total',
      dataIndex: 'mcr_total',
      sorter: (a, b) => a.mcr_total - b.mcr_total,
    },
    {
      title: 'MCR Closed',
      dataIndex: 'mcr_closed',
      sorter: (a, b) => a.mcr_closed - b.mcr_closed,
    },
    {
      title: 'Tags Total',
      dataIndex: 'tag_total',
      sorter: (a, b) => a.tag_total - b.tag_total,
    },
    {
      title: 'Tags with Punch',
      dataIndex: 'tag_with_punch',
      sorter: (a, b) => a.tag_with_punch - b.tag_with_punch,
    },
    {
      title: 'Progress',
      dataIndex: 'progress_pct',
      render: (value: number) => <Progress percent={Math.round(value ?? 0)} size="small" status="active" />,
    },
  ];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Typography.Title level={3} style={{ marginBottom: 0 }}>
        Subsystems Overview
      </Typography.Title>

      <Card>
        <Space size="large" wrap>
          <Statistic title="Total Tags" value={totals.tag_total} />
","metadata":{"exit_code":0,"duration_seconds":0.3}}

{"output":"          <Statistic title="Total Tags" value={totals.tag_total} />
          <Statistic
            title="MCR Closed"
            value={totals.mcr_total ? ((totals.mcr_closed / totals.mcr_total) * 100).toFixed(1) : '0.0'}
            suffix="%"
          />
          <Statistic title="Tags with Punch" value={totals.tag_with_punch} />
        </Space>
      </Card>

      <Card
        title="Subsystems"
        extra={
          <Space>
            <Input.Search
              placeholder="Search by system, subsystem or discipline"
              allowClear
              value={searchValue}
              onChange={(event) => setSearchValue(event.target.value)}
              style={{ width: 280 }}
            />
            <Button icon={<ReloadOutlined />} onClick={() => void loadSubsystems()} loading={loading}>
              Refresh
            </Button>
          </Space>
        }
      >
        {error && (
          <Alert
            type="error"
            message="Unable to load subsystems"
            description={error}
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}
        <Space wrap size="middle" style={{ marginBottom: 16 }}>
          <Select
            mode="multiple"
            allowClear
            placeholder="Discipline"
            value={selectedDisciplines}
            onChange={handleDisciplineChange}
            style={{ minWidth: 220 }}
            options={disciplineSelectOptions}
          />
          <Segmented
            options={[
              { label: 'All', value: 'all' },
              { label: '<50%', value: 'lt50' },
              { label: '50-90%', value: '50to90' },
              { label: '>90%', value: 'gt90' },
            ]}
            value={progressFilter}
            onChange={(value) => setProgressFilter(value as 'all' | 'lt50' | '50to90' | 'gt90')}
          />
          <Space>
            <Switch checked={onlyOpenPunch} onChange={setOnlyOpenPunch} />
            <Typography.Text>Only subsystems with open punches</Typography.Text>
          </Space>
        </Space>
        <Table<Subsystem>
          rowKey={(record) => `${record.sys_code}-${record.subsys_code}`}
          columns={columns}
          dataSource={filteredSubsystems}
          loading={loading}
          pagination={{ pageSize: 12 }}
          onRow={(record) => ({
            onClick: () =>
              navigate(`/subsystems/${encodeURIComponent(record.sys_code)}/${encodeURIComponent(record.subsys_code)}`),
            style: { cursor: 'pointer' },
          })}
        />
      </Card>
    </Space>
  );
};

export default SubsystemListPage;
